motion:
/* hook: a slow push on you walking in under the dead sign */
tl.fromTo("#hookfig", { scale: 1.0, transformOrigin: "50% 70%" }, { scale: 1.07, duration: 8.4, ease: "none" }, 3.8);
/* wide: the stripped aisle drifts */
tl.fromTo("#aisledark", { scale: 1.0 }, { scale: 1.08, duration: 4.8, ease: "none" }, 13.0);
/* rule 1 obeyed: the gauge reads 40L as you find it */
tl.fromTo("#tankgauge", { opacity: 0, scale: 0.7 }, { opacity: 1, scale: 1, duration: 0.4, ease: "power3.out" }, 23.6);
/* the plant: grid seven died on day one */
tl.fromTo("#gridbadge", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 28.6);
/* rule 2 obeyed: sixty feet */
tl.fromTo("#sixty", { scale: 1 }, { scale: 1.12, duration: 0.3, yoyo: true, repeat: 1, ease: "power2.inOut" }, 39.9);
/* radio */
tl.fromTo("#radiobox", { scale: 0.98 }, { scale: 1.04, duration: 4.8, ease: "none" }, 42.1);
tl.set("#radioline", { textContent: "" }, 42.1);
tl.to("#radioline", { duration: 1.3, scrambleText: { text: "AVOID ENCLOSED RETAIL", chars: "upperCase", speed: 0.6 } }, 44.4);
/* bad: you, at the back of the only exit */
tl.to("#youdot", { boxShadow: "0 0 0 18px rgba(255,66,66,0)", duration: 1.0, ease: "power2.out", repeat: 2 }, 57.9);
/* THE INCIDENT: every light at once */
tl.fromTo("#flash", { opacity: 0 }, { opacity: 0.92, duration: 0.06, ease: "none" }, 60.9);
tl.to("#flash", { opacity: 0, duration: 0.55, ease: "power2.out" }, 60.96);
tl.fromTo("#aislelit", { opacity: 0 }, { opacity: 1, duration: 0.2, ease: "none" }, 60.9);
/* the PA: sound rings */
[66.4, 67.0, 67.6].forEach((t, i) => {
  tl.fromTo(`#ring${i + 1}`, { scale: 1, opacity: 0.7 }, { scale: 1.9, opacity: 0, duration: 1.1, ease: "power2.out" }, t);
});
/* the lie: the sign that wants you to walk */
tl.fromTo("#checkout", { scale: 1 }, { scale: 1.06, duration: 0.6, yoyo: true, repeat: 5, ease: "sine.inOut" }, 70.0);
/* the recall: the stamp lands on "the lights are on" */
tl.fromTo("#onstamp", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 81.6);
